// jointEpochSQL is browseEpochSQL verbatim (cmd/mellifera/browse_wiring.go):
// the two-part naming-config horizon the drift check compares.
const jointEpochSQL = `
SELECT COALESCE(MAX(t.stamp), ''),
       (SELECT COUNT(*) FROM items  WHERE status <> 'deleted') +
       (SELECT COUNT(*) FROM series WHERE status <> 'deleted')
FROM (
  SELECT MAX(updated_at) AS stamp FROM title_overrides
  UNION ALL SELECT MAX(updated_at) FROM metadata_source_prefs
  UNION ALL SELECT MAX(updated_at) FROM modules
) t`

// jointComposer mirrors cmd/mellifera/browse_wiring.go's browseComposer:
// the store, the registry, the presentation closure, and the per-pass namer
// cache the resolver resolves through.
type jointComposer struct {
	st         *store.Store
	reg        *module.Registry
	modulePres func(context.Context, string, int64) (ModulePresentation, error)

	mu     sync.Mutex
	namers map[string]naming.Namer
}

func newJointComposer(st *store.Store, reg *module.Registry,
	modulePres func(context.Context, string, int64) (ModulePresentation, error),
) *jointComposer {
	return &jointComposer{st: st, reg: reg, modulePres: modulePres, namers: map[string]naming.Namer{}}
}

func (c *jointComposer) epoch() browse.Epoch {
	var stamp string
	var rows int64
	if err := c.st.DB().QueryRowContext(context.Background(), jointEpochSQL).Scan(&stamp, &rows); err != nil {
		return browse.Epoch{}
	}
	return browse.Epoch{UpdatedAt: stamp, Rows: rows}
}

// corpus clears the namer cache FIRST (the documented per-pass law — see the
// file comment), then walks the whole corpus.
func (c *jointComposer) corpus() ([]browse.Entry, map[string][]json.RawMessage, string) {
	c.mu.Lock()
	c.namers = map[string]naming.Namer{}
	c.mu.Unlock()
	out, err := c.walk(context.Background(), time.Time{})
	if err != nil {
		return nil, nil, ""
	}
	return out.entries, out.facetDocs, jointStamp(out.watermark)
}

func (c *jointComposer) changed(after string) ([]browse.Entry, string) {
	afterT, err := time.Parse(time.RFC3339Nano, after)
	if err != nil && after != "" {
		return nil, after
	}
	out, err := c.walk(context.Background(), afterT)
	if err != nil {
		return nil, after
	}
	return out.entries, jointStamp(out.watermark)
}

func (c *jointComposer) liveIDs() map[string]bool {
	out, err := c.walk(context.Background(), time.Time{})
	if err != nil {
		return nil
	}
	return out.liveIDs
}

// resolver is the About projection bound per library: MetadataFor wrapped
// with the library's pass-cached namer — the SAME resolver the About block
// serves (browse-scale OQ2), so facets can never grow a second walk.
func (c *jointComposer) resolver(libraryID string, raw json.RawMessage) map[string]any {
	n, err := c.namerCached(libraryID)
	if err != nil {
		return nil
	}
	return n.MetadataFor(raw)
}

func (c *jointComposer) facetDocs(libraryID string) []json.RawMessage {
	id, err := strconv.ParseInt(libraryID, 10, 64)
	if err != nil {
		return nil
	}
	rows, err := c.st.QuerySeries(context.Background(), id, "", access.System())
	if err != nil {
		return nil
	}
	docs := make([]json.RawMessage, 0, len(rows))
	for _, sr := range rows {
		if sr.Status != "deleted" {
			docs = append(docs, sr.Document)
		}
	}
	return docs
}

func (c *jointComposer) namerCached(libraryID string) (naming.Namer, error) {
	c.mu.Lock()
	n, ok := c.namers[libraryID]
	c.mu.Unlock()
	if ok {
		return n, nil
	}
	id, err := strconv.ParseInt(libraryID, 10, 64)
	if err != nil {
		return naming.Namer{}, err
	}
	ctx := context.Background()
	lib, err := c.st.GetLibrary(ctx, id, access.System())
	if err != nil {
		return naming.Namer{}, err
	}
	rows, err := c.st.QuerySeries(ctx, id, "", access.System())
	if err != nil {
		return naming.Namer{}, err
	}
	n, err = c.buildNamer(ctx, lib, rows)
	if err != nil {
		return naming.Namer{}, err
	}
	c.mu.Lock()
	c.namers[libraryID] = n
	c.mu.Unlock()
	return n, nil
}

// buildNamer mirrors browseComposer.buildNamer: the presentation closure
// handed the bare ctx (the zero-Viewer floor — the shared index is
// mute-blind; per-viewer muting lives at serve time).
func (c *jointComposer) buildNamer(ctx context.Context, lib store.Library, rows []store.Series) (naming.Namer, error) {
	pres, err := c.modulePres(ctx, lib.ModuleID, lib.ID)
	if err != nil {
		return naming.Namer{}, err
	}
	tmpl := lib.NamingElementName
	if tmpl == "" {
		tmpl = pres.ItemName
	}
	byPath := make(map[string]store.Series, len(rows))
	for _, sr := range rows {
		byPath[sr.RelativePath] = sr
	}
	return naming.Namer{
		GroupStyle:   lib.NamingGroupStyle,
		ElementTmpl:  tmpl,
		SeriesByPath: byPath,
		TitleSources: pres.TitleSources,
		LangPrefs:    pres.LanguagePreference,
		Chain:        pres.SourceChain,
		ModuleID:     lib.ModuleID,
	}, nil
}

type jointCorpus struct {
	entries   []browse.Entry
	facetDocs map[string][]json.RawMessage
	watermark time.Time
	liveIDs   map[string]bool
}

func (bc *jointCorpus) stamp(row time.Time) {
	if row.After(bc.watermark) {
		bc.watermark = row
	}
}

func (c *jointComposer) walk(ctx context.Context, after time.Time) (jointCorpus, error) {
	libs, err := c.st.ListLibraries(ctx, access.System())
	if err != nil {
		return jointCorpus{}, err
	}
	out := jointCorpus{
		entries:   make([]browse.Entry, 0),
		facetDocs: map[string][]json.RawMessage{},
		liveIDs:   map[string]bool{},
	}
	overrides := map[string]string{}
	override := func(entityID string) string {
		if so, ok := overrides[entityID]; ok {
			return so
		}
		so := ""
		if row, err := c.st.GetTitleOverride(ctx, entityID); err == nil {
			so = row.Title
		}
		overrides[entityID] = so
		return so
	}
	for _, lib := range libs {
		mod, err := c.reg.Get(lib.ModuleID)
		if err != nil || mod.MediaType == "image" {
			continue
		}
		rows, err := c.st.QuerySeries(ctx, lib.ID, "", access.System())
		if err != nil {
			continue
		}
		namer, err := c.buildNamer(ctx, lib, rows)
		if err != nil {
			continue
		}
		libID := strconv.FormatInt(lib.ID, 10)
		docs := make([]json.RawMessage, 0, len(rows))
		for _, sr := range rows {
			if sr.Status == "deleted" {
				continue
			}
			docs = append(docs, sr.Document)
			out.liveIDs[sr.ID] = true
			out.stamp(sr.UpdatedAt)
			if after.IsZero() || sr.UpdatedAt.After(after) {
				name := namer.SeriesName(sr, override(sr.ID))
				out.entries = append(out.entries, browse.Entry{
					ID:          sr.ID,
					LibraryID:   libID,
					Kind:        browse.KindSeries,
					DisplayName: name,
					Alternates:  jointServedAlternates(jointSeriesAlternates(namer, sr), name),
				})
			}
		}
		out.facetDocs[libID] = docs
		if err := c.walkItems(ctx, lib, namer, after, override, &out); err != nil {
			return jointCorpus{}, err
		}
	}
	return out, nil
}

func (c *jointComposer) walkItems(ctx context.Context, lib store.Library, namer naming.Namer,
	after time.Time, override func(string) string, out *jointCorpus,
) error {
	libID := strconv.FormatInt(lib.ID, 10)
	for offset := 0; ; offset += 1000 {
		batch, err := c.st.QueryItems(ctx, lib.ID, "", "", false, 1000, offset, access.System())
		if err != nil {
			return err
		}
		for _, it := range batch {
			if it.Status == "deleted" {
				continue
			}
			out.liveIDs[it.ID] = true
			out.stamp(it.UpdatedAt)
			if after.IsZero() || it.UpdatedAt.After(after) {
				n := namer
				if sr, _, _, ok := namer.ElementFacts(naming.DocMap(it.Document)); ok {
					n.SeriesOverride = override(sr.ID)
				}
				name := n.ItemName(it, override(it.ID))
				out.entries = append(out.entries, browse.Entry{
					ID:          it.ID,
					LibraryID:   libID,
					Kind:        browse.KindItem,
					DisplayName: name,
					Alternates:  jointServedAlternates(jointItemAlternates(namer, it), name),
				})
			}
		}
		if len(batch) < 1000 {
			return nil
		}
	}
}

func jointSeriesAlternates(n naming.Namer, sr store.Series) []string {
	doc := naming.DocMap(sr.Document)
	out := jointWalkTitles(n, doc)
	if parsed, ok := doc["parsed"].(map[string]any); ok {
		if raw, _ := parsed["dir_name_raw"].(string); raw != "" {
			out = append(out, raw)
		}
	}
	if seg := jointLastSegment(sr.RelativePath); seg != "" {
		out = append(out, seg)
	}
	return out
}

func jointItemAlternates(n naming.Namer, it store.Item) []string {
	doc := naming.DocMap(it.Document)
	out := jointWalkTitles(n, doc)
	if name, ok := n.ElementName(doc); ok {
		out = append(out, name)
	}
	out = append(out, jointViewTitleFloor(doc))
	return out
}

func jointWalkTitles(n naming.Namer, doc map[string]any) []string {
	var out []string
	sources, _ := doc["sources"].(map[string]any)
	for _, ts := range n.TitleSources {
		if !ts.Enabled {
			continue
		}
		ns, ok := sources[ts.ID].(map[string]any)
		if !ok {
			continue
		}
		switch title := ns["title"].(type) {
		case string:
			if title != "" {
				out = append(out, title)
			}
		case map[string]any:
			for _, v := range title {
				if s, is := v.(string); is && s != "" {
					out = append(out, s)
				}
			}
		}
	}
	if parser, ok := sources["serial-parser"].(map[string]any); ok {
		if title, _ := parser["title"].(string); title != "" {
			out = append(out, title)
		}
	}
	return out
}

func jointViewTitleFloor(doc map[string]any) string {
	view, ok := doc["_view"].(map[string]any)
	if !ok {
		return ""
	}
	title, ok := view["title"].(map[string]any)
	if !ok {
		return ""
	}
	v, _ := title["value"].(string)
	return v
}

func jointLastSegment(relPath string) string {
	for i := len(relPath) - 1; i >= 0; i-- {
		if relPath[i] == '/' {
			return relPath[i+1:]
		}
	}
	return relPath
}

func jointServedAlternates(candidates []string, winner string) []string {
	seen := map[string]bool{winner: true}
	out := make([]string, 0, len(candidates))
	for _, c := range candidates {
		if c == "" || seen[c] {
			continue
		}
		seen[c] = true
		out = append(out, c)
	}
	return out
}

func jointStamp(t time.Time) string {
	if t.IsZero() {
		return ""
	}
	return t.UTC().Format(time.RFC3339Nano)
}

// jointPresentationClosure mirrors cmd's newModulePresentationClosure over the
// real registry + store prefs: ResolveGates inherit-then-override, the
// viewer's chain mutes ANDed down post-resolution on the copies (the bare
// walk ctx reads a zero Viewer — a no-op), the title walk and the served
// chain assembled through the Add* construction paths. The refresh-source
// leg keys on loadedCaps, empty here (no plugins load in the test process).
func jointPresentationClosure(st *store.Store, reg *module.Registry) func(context.Context, string, int64) (ModulePresentation, error) {
	loadedCaps := map[string][]string{}
	return func(ctx context.Context, moduleID string, libraryID int64) (ModulePresentation, error) {
		m, err := reg.Get(moduleID)
		if err != nil {
			return ModulePresentation{}, err
		}
		prefs, err := st.ListMetadataSourcePrefs(ctx, moduleID, []int64{libraryID})
		if err != nil {
			return ModulePresentation{}, err
		}
		gated := enrich.ResolveGates(m, prefs, libraryID)
		viewer := access.FromContext(ctx)
		for i := range gated {
			if viewer.ChainMutes[gated[i].PluginID] {
				gated[i].Enabled = false
			}
		}
		byID := make(map[string]module.MetadataSourceBinding, len(gated))
		for _, src := range gated {
			byID[src.PluginID] = src
		}
		pres := ModulePresentation{
			ItemName:           m.ItemName,
			LanguagePreference: append([]string(nil), m.LanguagePreference...),
		}
		for _, id := range m.TitleSourcePriority {
			src, ok := byID[id]
			if !ok {
				continue
			}
			pres.AddTitleSource(id, src.Enabled)
			if _, loaded := loadedCaps[id]; loaded && src.Enabled {
				pres.AddRefreshSource(id, src.Enabled)
			}
		}
		for _, src := range gated {
			pres.AddChainSource(src.PluginID, src.Enabled)
		}
		return pres, nil
	}
}

// jointFixture is the seeded corpus + the three wired routers over ONE
// browse.Service and ONE api.Deps: the operator router (admin principal,
// granted viewer) for the mutating admin routes, and the two viewer routers
// (client principals) for the granted/denied reads — the handlers_viewer_test
// two-viewer posture.
type jointFixture struct {
	st                              *store.Store
	svc                             *browse.Service
	wake                            <-chan struct{}
	libFix, libDeny                 int64
	aria, yolka, hidden             store.Series
	ep1, ep2, hiddenEp              store.Item
	op, grantedRouter, deniedRouter http.Handler
}

// newJointFixture seeds two serial libraries — libFix («Ария» with the
// shikimori About carrier + «Ёлка» for the ё→е fold; anchored S01E01/S01E02
// episodes) and libDeny ("Скрытый" + one episode) — warms the index once
// (the janitor boot-run), and builds the routers. Progress rides the
// two-grant writer (UserID 99 sees BOTH libraries at write time; the readers'
// narrower grants are the revoked-grant posture of handlers_viewer_test).
func newJointFixture(t *testing.T) *jointFixture {
	t.Helper()
	ctx := context.Background()
	st := openAPIStore(t)
	reg, err := module.Open(ctx, st)
	if err != nil {
		t.Fatalf("module.Open: %v", err)
	}
	libFix, err := st.CreateLibrary(ctx, "serial", "/media/fix", "Fixture")
	if err != nil {
		t.Fatalf("CreateLibrary fix: %v", err)
	}
	libDeny, err := st.CreateLibrary(ctx, "serial", "/media/deny", "DenyLib")
	if err != nil {
		t.Fatalf("CreateLibrary deny: %v", err)
	}

	shikimori := func(title map[string]any, desc string, genres []string, kind, status string) map[string]any {
		return map[string]any{"title": title, "description": desc, "genres": genres, "kind": kind, "status": status}
	}
	aria := seedRecsSeries(t, st, libFix, "aria-1999", map[string]any{
		"parsed":  map[string]any{"backing": "directory", "dir_name_raw": "aria-1999"},
		"sources": map[string]any{"shikimori": shikimori(map[string]any{"russian": "Ария", "romaji": "Aria"}, "Рок-легенда", []string{"Rock", "Power Metal"}, "tv", "ongoing")},
	})
	yolka := seedRecsSeries(t, st, libFix, "yolka-2001", map[string]any{
		"parsed":  map[string]any{"backing": "directory", "dir_name_raw": "yolka-2001"},
		"sources": map[string]any{"shikimori": shikimori(map[string]any{"russian": "Ёлка", "romaji": "Yolka"}, "Зимняя сказка", []string{"Rock"}, "tv", "completed")},
	})
	hidden := seedRecsSeries(t, st, libDeny, "hidden-show", map[string]any{
		"parsed":  map[string]any{"backing": "directory", "dir_name_raw": "hidden-show"},
		"sources": map[string]any{"shikimori": shikimori(map[string]any{"russian": "Скрытый", "romaji": "Hidden Show"}, "Ничего не видно", []string{"Drama"}, "tv", "ongoing")},
	})

	episode := func(seriesPath string, season, ep int64, epTitle string) map[string]any {
		return map[string]any{
			"parsed": map[string]any{"series_relative_path": seriesPath},
			"sources": map[string]any{
				"serial-parser": map[string]any{"season": season, "episode": ep},
				"shikimori":     map[string]any{"title": epTitle},
			},
		}
	}
	ep1 := seedRecsItem(t, st, libFix, "itm_aria_e1", "aria-1999/aria S01E01.mkv", func() map[string]any {
		d := episode("aria-1999", 1, 1, "Эпизод один")
		d["ffprobe"] = map[string]any{"format": map[string]any{"duration": "1234.6"}}
		return d
	}(), time.Time{})
	ep2 := seedRecsItem(t, st, libFix, "itm_aria_e2", "aria-1999/aria S01E02.mkv", episode("aria-1999", 1, 2, "Эпизод два"), time.Time{})
	hiddenEp := seedRecsItem(t, st, libDeny, "itm_hidden_e1", "hidden-show/hidden S01E01.mkv", episode("hidden-show", 1, 1, "Скрытая серия"), time.Time{})

	writer := access.User(99, []int64{libFix, libDeny}, nil)
	if _, err := st.PutProgress(ctx, hiddenEp.ID, 300, writer); err != nil {
		t.Fatalf("PutProgress hidden: %v", err)
	}
	if _, err := st.PutProgress(ctx, ep1.ID, 500, writer); err != nil {
		t.Fatalf("PutProgress ep1: %v", err)
	}

	modulePres := jointPresentationClosure(st, reg)
	comp := newJointComposer(st, reg, modulePres)
	svc := browse.NewService(browse.Deps{
		Epoch:     comp.epoch,
		Corpus:    comp.corpus,
		Changed:   comp.changed,
		LiveIDs:   comp.liveIDs,
		Resolver:  comp.resolver,
		FacetDocs: comp.facetDocs,
	})
	svc.Build() // the boot-warm: the index is hot before any request

	deps := Deps{
		AdminToken:         adminToken,
		Store:              st,
		Scan:               func(context.Context, int64) (scan.Result, error) { return scan.Result{}, nil },
		Art:                art.NewService(st, t.TempDir()),
		ModulePresentation: modulePres,
		SourceInventory: func(context.Context) ([]string, map[string]string, map[string]string) {
			mods, _ := reg.List()
			var ids []string
			seen := map[string]bool{}
			names := map[string]string{}
			descriptions := map[string]string{}
			for _, m := range mods {
				for _, src := range m.MetadataSources {
					if seen[src.PluginID] {
						continue
					}
					seen[src.PluginID] = true
					ids = append(ids, src.PluginID)
					names[src.PluginID] = src.PluginID
					descriptions[src.PluginID] = "joint fixture source"
				}
			}
			return ids, names, descriptions
		},
		BrowseSearch: func(query string) ([]string, []string) {
			hits := svc.Search(query)
			return hits.Series, hits.Items
		},
		LibraryFacets: func(libraryID int64) ([]string, [][]string, [][]int) {
			fs := svc.Facets(strconv.FormatInt(libraryID, 10))
			keys := make([]string, len(fs))
			values := make([][]string, len(fs))
			counts := make([][]int, len(fs))
			for i, f := range fs {
				keys[i] = f.Key
				values[i] = make([]string, len(f.Values))
				counts[i] = make([]int, len(f.Values))
				for j, v := range f.Values {
					values[i][j] = v.Value
					counts[i][j] = v.Count
				}
			}
			return keys, values, counts
		},
		OnTitleChange:       func(context.Context, string) { svc.Wake() },
		OnSourceGateChanged: func(context.Context, int64) { svc.Wake() },
	}

	router := func(role Role, v access.Viewer) http.Handler {
		h := &app{deps: deps}
		r := chi.NewRouter()
		r.Use(principalInjector(role))
		r.Use(principalViewerInjector(v))
		r.Route("/api/v1", func(r chi.Router) { mountV1Routes(r, h) })
		return r
	}
	granted := access.User(99, []int64{libFix, libDeny}, nil)
	denied := access.User(99, []int64{libDeny}, nil)
	return &jointFixture{
		st: st, svc: svc, wake: svc.WakeChan(),
		libFix: libFix, libDeny: libDeny,
		aria: aria, yolka: yolka, hidden: hidden,
		ep1: ep1, ep2: ep2, hiddenEp: hiddenEp,
		op:            router(RoleAdmin, granted),
		grantedRouter: router(RoleClient, granted),
		deniedRouter:  router(RoleClient, denied),
	}
}

// jointGetSearch fires GET /search?q=… and decodes both hit groups.
func jointGetSearch(t *testing.T, h http.Handler, q string) searchResponse {
	t.Helper()
	resp := doRequest(t, h, http.MethodGet, "/api/v1/search?"+url.Values{"q": {q}}.Encode(), "", adminToken)
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		t.Fatalf("GET /search q=%q: status = %d, want 200", q, resp.StatusCode)
	}
	var sr searchResponse
	if err := json.NewDecoder(resp.Body).Decode(&sr); err != nil {
		t.Fatalf("decode searchResponse: %v", err)
	}
	return sr
}

// jointIDs extracts an id set from one hit group.
func jointIDs[T any](rows []T, id func(T) string) map[string]bool {
	out := make(map[string]bool, len(rows))
	for _, r := range rows {
		out[id(r)] = true
	}
	return out
}

func TestBrowseScaleJoint(t *testing.T) {
	fx := newJointFixture(t)

	// Clause 1 — the Cyrillic query hits through the fold: q=АРИЯ (upper
	// Cyrillic) matches the composed «Ария» on the prefix tier AND its
	// episodes on the composed item names; q=елка matches «Ёлка» through the
	// ё→е index-side fold; q=aria recalls the series through its alternate
	// (the losing English name), with no item matches (the episodes carry no
	// Latin match surface).
	t.Run("cyrillic_fold_hits", func(t *testing.T) {
		qАрия := jointGetSearch(t, fx.grantedRouter, "АРИЯ")
		if !jointIDs(qАрия.Series, func(d seriesDTO) string { return d.ID })[fx.aria.ID] {
			t.Fatalf("q=АРИЯ series hits %v, want %q", qАрия.Series, fx.aria.ID)
		}
		gotItems := jointIDs(qАрия.Items, func(d itemDTO) string { return d.ID })
		if !gotItems[fx.ep1.ID] || !gotItems[fx.ep2.ID] || len(gotItems) != 2 {
			t.Fatalf("q=АРИЯ item hits %v, want exactly %q + %q", qАрия.Items, fx.ep1.ID, fx.ep2.ID)
		}
		qЕлка := jointGetSearch(t, fx.grantedRouter, "елка")
		if len(qЕлка.Series) != 1 || qЕлка.Series[0].ID != fx.yolka.ID {
			t.Fatalf("q=елка series hits %v, want exactly %q (the ё→е fold)", qЕлка.Series, fx.yolka.ID)
		}
		qAria := jointGetSearch(t, fx.grantedRouter, "aria")
		if len(qAria.Series) != 1 || qAria.Series[0].ID != fx.aria.ID {
			t.Fatalf("q=aria series hits %v, want %q via its alternate", qAria.Series, fx.aria.ID)
		}
		if len(qAria.Items) != 0 {
			t.Fatalf("q=aria item hits %v, want none", qAria.Items)
		}
	})

	// Clause 3 — the facet counts equal the About resolver's output: derive
	// the expected per-key counts from the About blocks the series LISTING
	// serves (the same MetadataFor projection), compare with /facets
	// verbatim — values, counts, and the serving order (count desc, value
	// asc). The detail route pins one full About block first.
	t.Run("facet_counts_equal_about_resolver", func(t *testing.T) {
		resp := doRequest(t, fx.grantedRouter, http.MethodGet, "/api/v1/series/"+fx.aria.ID, "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("GET /series/%s: status = %d, want 200", fx.aria.ID, resp.StatusCode)
		}
		var detail seriesResponse
		if err := json.NewDecoder(resp.Body).Decode(&detail); err != nil {
			t.Fatalf("decode seriesResponse: %v", err)
		}
		about, _ := detail.Series.Metadata["about"].(map[string]any)
		if about["source"] != "shikimori" || about["description"] != "Рок-легенда" || about["kind"] != "tv" || about["status"] != "ongoing" {
			t.Fatalf("aria About = %v, want the shikimori carrier whole", about)
		}

		resp = doRequest(t, fx.grantedRouter, http.MethodGet, "/api/v1/series?library="+strconv.FormatInt(fx.libFix, 10), "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("GET /series?library: status = %d, want 200", resp.StatusCode)
		}
		var listing seriesListResponse
		if err := json.NewDecoder(resp.Body).Decode(&listing); err != nil {
			t.Fatalf("decode seriesListResponse: %v", err)
		}
		if len(listing.Items) != 2 {
			t.Fatalf("fixture series count = %d, want 2", len(listing.Items))
		}
		expected := map[string]map[string]int{"genres": {}, "kind": {}, "status": {}}
		for _, s := range listing.Items {
			ab, _ := s.Metadata["about"].(map[string]any)
			if ab == nil {
				t.Fatalf("series %s carries no About block", s.ID)
			}
			if genres, ok := ab["genres"].([]any); ok {
				for _, g := range genres {
					expected["genres"][g.(string)]++
				}
			}
			if k, ok := ab["kind"].(string); ok {
				expected["kind"][k]++
			}
			if st, ok := ab["status"].(string); ok {
				expected["status"][st]++
			}
		}

		resp = doRequest(t, fx.grantedRouter, http.MethodGet, "/api/v1/libraries/"+strconv.FormatInt(fx.libFix, 10)+"/facets", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("GET /facets: status = %d, want 200", resp.StatusCode)
		}
		var fr facetsResponse
		if err := json.NewDecoder(resp.Body).Decode(&fr); err != nil {
			t.Fatalf("decode facetsResponse: %v", err)
		}
		got := map[string]map[string]int{}
		for _, f := range fr.Facets {
			got[f.Key] = map[string]int{}
			for _, v := range f.Values {
				got[f.Key][v.Value] = v.Count
			}
			// The serving order law: count desc, value asc.
			for j := 1; j < len(f.Values); j++ {
				prev, cur := f.Values[j-1], f.Values[j]
				if prev.Count < cur.Count || (prev.Count == cur.Count && prev.Value > cur.Value) {
					t.Fatalf("facet %s values out of serving order: %v", f.Key, f.Values)
				}
			}
		}
		if len(got["genres"]) != 2 || got["genres"]["Rock"] != 2 || got["genres"]["Power Metal"] != 1 {
			t.Fatalf("genres facet = %v, want Rock:2 Power Metal:1", got["genres"])
		}
		if got["kind"]["tv"] != 2 {
			t.Fatalf("kind facet = %v, want tv:2", got["kind"])
		}
		if got["status"]["ongoing"] != 1 || got["status"]["completed"] != 1 {
			t.Fatalf("status facet = %v, want ongoing:1 completed:1", got["status"])
		}
		for key, want := range expected {
			if len(want) != len(got[key]) {
				t.Fatalf("facet %s = %v, want the About-derived %v", key, got[key], want)
			}
			for value, count := range want {
				if got[key][value] != count {
					t.Fatalf("facet %s[%q] = %d, want the About-derived %d", key, value, got[key][value], count)
				}
			}
		}
	})

	// Clause 4 — /home answers in exactly ONE request: the single GET
	// carries the COMPLETE composition the rail renders — the scored rows,
	// the live-composed display names, the raw episode facts, the episode
	// title, the ffprobe duration floor, and the next-episode pick — so the
	// SPA needs no follow-up request for it (the server half of the
	// one-request law; the SPA-side count is 5.3's vitest).
	t.Run("home_answers_in_one_request", func(t *testing.T) {
		resp := doRequest(t, fx.grantedRouter, http.MethodGet, "/api/v1/home", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("GET /home: status = %d, want 200", resp.StatusCode)
		}
		var hr homeResponse
		if err := json.NewDecoder(resp.Body).Decode(&hr); err != nil {
			t.Fatalf("decode homeResponse: %v", err)
		}
		if len(hr.Continue) != 2 {
			t.Fatalf("home rows = %d, want 2 (one per seeded progress row)", len(hr.Continue))
		}
		var ariaRow, hiddenRow *continueRow
		for i := range hr.Continue {
			switch hr.Continue[i].Current.ItemID {
			case fx.ep1.ID:
				ariaRow = &hr.Continue[i]
			case fx.hiddenEp.ID:
				hiddenRow = &hr.Continue[i]
			}
		}
		if ariaRow == nil || hiddenRow == nil {
			t.Fatalf("home rows missing the seeded items: %+v", hr.Continue)
		}
		if ariaRow.SeriesID != fx.aria.ID || ariaRow.SeriesDisplay != "Ария" ||
			ariaRow.LibraryID != fx.libFix || ariaRow.LibraryName != "Fixture" {
			t.Fatalf("aria row header = %+v, want the composed «Ария» over Fixture", ariaRow)
		}
		cur := ariaRow.Current
		if cur.Display != "Ария · S01E01" || cur.Season == nil || *cur.Season != 1 ||
			cur.Episode == nil || *cur.Episode != 1 || cur.EpisodeTitle != "Эпизод один" ||
			cur.PositionSeconds != 500 || cur.DurationSeconds == nil || *cur.DurationSeconds != 1235 {
			t.Fatalf("aria current = %+v, want the one-request composition", cur)
		}
		if ariaRow.Next == nil || ariaRow.Next.ItemID != fx.ep2.ID || ariaRow.Next.Label != "S01E02" {
			t.Fatalf("aria next = %+v, want %q S01E02", ariaRow.Next, fx.ep2.ID)
		}
		if hiddenRow.Next != nil || hiddenRow.Current.DurationSeconds != nil {
			t.Fatalf("hidden row = %+v, want no next and no duration (honest absence)", hiddenRow)
		}
	})

	// Clause 7 — the invisible library: two viewers over the SAME index and
	// routes; the denied viewer (libDeny only) gets NO /search hits, no
	// facet counts, and no /home rows from libFix — not even a leak of the
	// ids or names in the raw bytes — while its OWN library still serves
	// (the denial is scoped, never a blanket) and the granted viewer sees
	// everything.
	t.Run("invisible_library_two_viewers", func(t *testing.T) {
		denied := jointGetSearch(t, fx.deniedRouter, "АРИЯ")
		if len(denied.Series) != 0 || len(denied.Items) != 0 {
			t.Fatalf("denied q=АРИЯ = %d series + %d items, want none", len(denied.Series), len(denied.Items))
		}
		granted := jointGetSearch(t, fx.grantedRouter, "АРИЯ")
		if !jointIDs(granted.Series, func(d seriesDTO) string { return d.ID })[fx.aria.ID] {
			t.Fatalf("granted q=АРИЯ series = %v, want %q", granted.Series, fx.aria.ID)
		}
		both := jointGetSearch(t, fx.deniedRouter, "hidden")
		if !jointIDs(both.Series, func(d seriesDTO) string { return d.ID })[fx.hidden.ID] {
			t.Fatalf("denied q=hidden series = %v, want its OWN library's hit", both.Series)
		}

		resp := doRequest(t, fx.deniedRouter, http.MethodGet, "/api/v1/libraries/"+strconv.FormatInt(fx.libFix, 10)+"/facets", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusNotFound {
			t.Fatalf("denied /facets status = %d, want 404", resp.StatusCode)
		}
		if eb := decodeError(t, resp); eb.Error.Code != "not_found" {
			t.Fatalf("denied /facets error = %s, want not_found", eb.Error.Code)
		}

		// /home: the denied viewer keeps its own row; nothing of libFix —
		// ids, names, or counts — appears anywhere in the body bytes.
		resp = doRequest(t, fx.deniedRouter, http.MethodGet, "/api/v1/home", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("denied /home status = %d, want 200", resp.StatusCode)
		}
		body, _ := io.ReadAll(resp.Body)
		var deniedHome homeResponse
		if err := json.Unmarshal(body, &deniedHome); err != nil {
			t.Fatalf("decode denied homeResponse: %v", err)
		}
		if len(deniedHome.Continue) != 1 || deniedHome.Continue[0].Current.ItemID != fx.hiddenEp.ID {
			t.Fatalf("denied home rows = %+v, want only the hidden episode", deniedHome.Continue)
		}
		for _, leak := range []string{fx.aria.ID, fx.ep1.ID, fx.ep2.ID, "Ария", "aria-1999", "Fixture"} {
			if bytes.Contains(body, []byte(leak)) {
				t.Fatalf("denied /home body leaks %q: %s", leak, body)
			}
		}
		resp = doRequest(t, fx.grantedRouter, http.MethodGet, "/api/v1/home", "", adminToken)
		defer resp.Body.Close()
		var grantedHome homeResponse
		if err := json.NewDecoder(resp.Body).Decode(&grantedHome); err != nil {
			t.Fatalf("decode granted homeResponse: %v", err)
		}
		if len(grantedHome.Continue) != 2 {
			t.Fatalf("granted home rows = %d, want 2", len(grantedHome.Continue))
		}
	})

	// Clause 5 — the title-override rename reflects in search immediately:
	// the pre-state misses the new name; the PUT fires the OnTitleChange
	// poke synchronously before its response (the buffered wake holds the
	// token — deterministic, no sleep); one Reconcile (the tick's body)
	// trips the epoch drift and rebuilds; the NEW name hits the recomposed
	// series AND its recomposed episode entries — a stale index could never
	// answer it, since serving composes live but the HIT decision is the
	// index's (D3). The old name keeps recalling through its alternate (the
	// losing-name law), which is why the new-name hit is the rebuild proof.
	t.Run("title_override_rename_reflects_immediately", func(t *testing.T) {
		if pre := jointGetSearch(t, fx.grantedRouter, "Новое Имя"); len(pre.Series) != 0 || len(pre.Items) != 0 {
			t.Fatalf("pre-rename q=Новое Имя hit %v / %v, want nothing", pre.Series, pre.Items)
		}
		resp := doRequest(t, fx.op, http.MethodPut, "/api/v1/series/"+fx.aria.ID+"/title", `{"title":"Новое Имя"}`, adminToken)
		resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("PUT title status = %d, want 200", resp.StatusCode)
		}
		select {
		case <-fx.wake:
		default:
			t.Fatal("no wake token after the title PUT — OnTitleChange did not poke")
		}
		fx.svc.Reconcile()
		post := jointGetSearch(t, fx.grantedRouter, "Новое Имя")
		if !jointIDs(post.Series, func(d seriesDTO) string { return d.ID })[fx.aria.ID] {
			t.Fatalf("post-rename q=Новое Имя series = %v, want %q", post.Series, fx.aria.ID)
		}
		items := jointIDs(post.Items, func(d itemDTO) string { return d.ID })
		if !items[fx.ep1.ID] || !items[fx.ep2.ID] {
			t.Fatalf("post-rename q=Новое Имя items = %v, want the recomposed episodes", post.Items)
		}
		if old := jointGetSearch(t, fx.grantedRouter, "АРИЯ"); !jointIDs(old.Series, func(d seriesDTO) string { return d.ID })[fx.aria.ID] {
			t.Fatalf("q=АРИЯ after rename = %v, want the alternate recall", old.Series)
		}
	})

	// Clause 6 — the source-gate flip drops that source's genre facet within
	// one reconcile tick: disabling shikimori (libFix scope) fires NO poke
	// (a disable wakes nothing — dormancy is read-time), so the buffered
	// channel must be EMPTY after the PUT; one Reconcile trips the epoch
	// drift (the pref write bumps metadata_source_prefs.updated_at), the
	// rebuild recomposes under the current gates, and shikimori — the only
	// About description carrier — gone, the genre facet drops WHOLE.
	t.Run("gate_flip_drops_genre_facet", func(t *testing.T) {
		select {
		case <-fx.wake:
			t.Fatal("unexpected wake token before the gate flip")
		default:
		}
		resp := doRequest(t, fx.op, http.MethodPut,
			"/api/v1/libraries/"+strconv.FormatInt(fx.libFix, 10)+"/sources/shikimori",
			`{"enabled":false}`, adminToken)
		resp.Body.Close()
		if resp.StatusCode != http.StatusNoContent {
			t.Fatalf("gate PUT status = %d, want 204", resp.StatusCode)
		}
		select {
		case <-fx.wake:
			t.Fatal("gate DISABLE poked the index — dormancy must converge via the tick")
		default:
		}
		fx.svc.Reconcile()
		resp = doRequest(t, fx.grantedRouter, http.MethodGet, "/api/v1/libraries/"+strconv.FormatInt(fx.libFix, 10)+"/facets", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("post-flip /facets status = %d, want 200", resp.StatusCode)
		}
		var fr facetsResponse
		if err := json.NewDecoder(resp.Body).Decode(&fr); err != nil {
			t.Fatalf("decode facetsResponse: %v", err)
		}
		if len(fr.Facets) != 0 {
			t.Fatalf("post-flip facets = %+v, want every shikimori-carried facet dropped", fr.Facets)
		}
		// The denied library never carried the gate — its resolution is
		// untouched, proving the flip was scoped to libFix.
		resp = doRequest(t, fx.grantedRouter, http.MethodGet, "/api/v1/libraries/"+strconv.FormatInt(fx.libDeny, 10)+"/facets", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("libDeny /facets status = %d, want 200", resp.StatusCode)
		}
		if err := json.NewDecoder(resp.Body).Decode(&fr); err != nil {
			t.Fatalf("decode libDeny facetsResponse: %v", err)
		}
		if len(fr.Facets) == 0 {
			t.Fatal("libDeny facets dropped too — the flip leaked across libraries")
		}
	})
}
